"""Explicit platform-owner support. No impersonation or operational execution."""
import copy,re
from html import escape
from fastapi.responses import HTMLResponse,JSONResponse
from . import fresh
from .core import Invalid,digest
COOKIE='__Host-flux_support'
async def rpc(store,action,args=None):
 r=await store.CLIENT.post(fresh.URL+'/rest/v1/rpc/flux_owner_support',headers=dict(fresh.HEAD),json={'action':action,'args':args or {}})
 if r.status_code!=200:raise Invalid('Support access denied, expired, or draft changed. Return to Client Support and reload.')
 return r.json()
def corrected(body,changes,actor,now):
 if not isinstance(changes,dict) or set(changes)-{'name','responsibility'}:raise Invalid('Choose a draft name or responsibility correction')
 for k,v in changes.items():
  if not isinstance(v,str) or not 1<=len(v.strip())<=(160 if k=='name' else 4000):raise Invalid('Supply a valid '+k)
 if body.get('status')!='draft' or not re.fullmatch(r'\d+\.\d+\.\d+',body.get('version','')):raise Invalid('Only versioned drafts can be corrected')
 b=copy.deepcopy(body);parts=b['version'].split('.');parts[-1]=str(int(parts[-1])+1);b['version']='.'.join(parts)
 b.update({k:v.strip() for k,v in changes.items()});b.update(actor=actor,created_at=now,status='draft',draft_revision=b['version'],release_version=None)
 if b.get('guided'):
  b['guided'].update({k:v.strip() for k,v in changes.items()});b['guided']['version']=b['version'];b['guided_hash']=digest(b['guided'])
 if 'execution_enabled' in b:b['execution_enabled']=False
 b['content_hash']=digest({k:v for k,v in b.items() if k!='content_hash'})
 return b
async def browser(request,store):
 path=request.url.path
 if path=='/api/owner-support/status':
  result=await rpc(store,'status');result['show_console']=bool(result['enabled'] and fresh.CTX.get()['client']['id']==result.get('home_client'));return JSONResponse(result)
 if path in ('/owner-support','/owner-support/view'):
  state=await rpc(store,'status')
  if not state['enabled']:return JSONResponse({'detail':'Platform owner support permission required'},403)
  return HTMLResponse(PAGE,headers={'Cache-Control':'no-store','Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'"})
 if path=='/guidance':return HTMLResponse(GUIDANCE,headers={'Cache-Control':'no-store'})
 if path=='/api/support-guidance':
  c=fresh.CTX.get()
  if not c.get('company'):return JSONResponse({'notes':[]})
  return JSONResponse(await fresh.rest(store,'POST','rpc/flux_support_guidance',{'client':c['client']['id'],'company':c['company']['id']}))
 action=path.removeprefix('/api/owner-support/')
 allowed={'clients':'GET','snapshot':'GET','audit':'GET','open':'POST','close':'POST','note':'POST','correct':'POST'}
 if action not in allowed or request.method!=allowed[action]:return JSONResponse({'detail':'Support operation denied'},405)
 b=await request.json() if request.method=='POST' else dict(request.query_params)
 from .mcp_connection import no_secrets
 no_secrets(b)
 if action=='open':
  x=await rpc(store,'open',b);response=JSONResponse({k:v for k,v in x.items() if k!='token'});fresh.cookie(response,COOKIE,x['token'],1800);return response
 if action not in ('clients','audit'):b['session']=request.cookies.get(COOKIE,'')
 if action=='correct':
  # Re-read the chosen scope and enforce the submitted hash again in the database.
  snapshot=await rpc(store,'snapshot',{k:b.get(k) for k in ('client','company','session')});current=next((x for x in snapshot['objects'] if x['path']==b.get('path')),None)
  if not current or current['record_hash']!=b.get('expected_hash') or current.get('published'):raise Invalid('Draft changed or is published. Reload before editing.')
  changes=b['changes']
  if current['path'].startswith('workflows/') and 'responsibility' in changes:raise Invalid('Workflow corrections change the draft name only')
  b['body']=corrected(current['body'],changes,store.ACTOR.get(),store.now());action='save_draft'
 result=await rpc(store,action,b)
 if action=='snapshot':
  from .discovery import QUESTION_SETS
  for item in result['discovery']:item['questions']=[{'id':'q'+str(i+1),'question':q} for i,q in enumerate(QUESTION_SETS.get(item['questionnaire_version'],[]))]
 response=JSONResponse(result)
 if action=='close':response.delete_cookie(COOKIE,secure=True,httponly=True,samesite='strict',path='/')
 return response
PAGE='''<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>n0v8v · Client Support</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101923;color:#eef4f6;font:16px system-ui;line-height:1.55}main{max-width:1180px;margin:30px auto;padding:24px}a{color:#80dec3}h1{margin-bottom:6px}h2,h3{line-height:1.25}p{overflow-wrap:anywhere}.muted,small{color:#b7c6d0}button,input,select,textarea{font:inherit;padding:11px 14px;border:1px solid #536779;border-radius:8px;background:#1b2b3b;color:inherit}button{cursor:pointer}button:disabled{opacity:.4}input,textarea{width:100%}textarea{min-height:115px}label{display:block;margin:12px 0}button.primary{background:#80dec3;color:#10241f;border:0;font-weight:650}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px;margin-top:24px}article,section.panel{background:#162434;border:1px solid #3c5061;padding:20px;border-radius:12px;margin-bottom:16px}article h2{margin-top:0}article select{width:100%;margin-bottom:12px}.row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.split{display:grid;grid-template-columns:2fr 1fr;gap:24px}#banner{position:sticky;top:0;z-index:3;background:#294740;border-bottom:1px solid #80dec3;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;gap:12px}#banner[hidden]{display:none}#status{position:sticky;bottom:0;background:#101923;padding:14px;color:#96e5cc}#error{color:#ffbaaf}details{margin:14px 0}summary{cursor:pointer}nav{display:flex;gap:8px;margin:20px 0;flex-wrap:wrap}nav button[aria-pressed=true]{border-color:#80dec3}dl{margin:10px 0}dt{font-weight:650}dd{margin-left:0;margin-bottom:12px}dialog{width:min(600px,95vw);background:#162434;color:inherit;border:1px solid #809ba9;border-radius:12px;padding:24px}dialog::backdrop{background:#0009}@media(max-width:760px){main{padding:16px}.split{grid-template-columns:1fr}#banner{align-items:flex-start;font-size:14px}}
</style></head><body><div id="banner" hidden><div><strong>OWNER SUPPORT · <span id="target"></span></strong><div id="actor"></div><small id="expiry"></small></div><button id="exit">Exit support</button></div><main><div class="row"><a href="/">← My workspace</a><a href="/owner-support">Client Support</a><button id="show-audit">Private admin audit</button></div><h1 id="title">Client Support</h1><p id="intro">Open a company to review its configuration, leave guidance or correct a draft. Opening a view creates no business run.</p><p id="error" role="alert"></p><div id="console"><label>Find a client<input id="search" placeholder="Company name or client code"></label><div id="cards" class="grid"></div></div><div id="view" hidden><div class="split"><div><nav id="tabs"></nav><div id="content"></div></div><aside><section class="panel"><h2>Leave guidance</h2><p class="muted">Saved notes are visible to this company in Owner guidance. They do not create a workflow execution.</p><form id="note"><label>Type<select id="category"><option value="suggestion">Suggestion</option><option value="correction">Correction</option><option value="guidance">Guidance</option></select></label><label>Note<textarea id="note-text" maxlength="10000" required></textarea></label><button class="primary">Save note</button></form></section><section class="panel"><h2>Company notes</h2><div id="notes"></div></section></aside></div></div><section id="audit" class="panel" hidden><h2>Private admin audit</h2><div id="events"></div></section><p id="status" role="status" aria-live="polite"></p></main><dialog id="purpose"><form id="purpose-form"><h2>Open company support</h2><p id="purpose-target"></p><label>Support purpose<input id="reason" maxlength="1000" required value="Review configuration and provide guidance"></label><div class="row"><button class="primary">Open client view</button><button type="button" id="cancel-open">Cancel</button></div></form></dialog><dialog id="correction"><form id="correction-form"><h2>Correct a draft</h2><p id="draft-version"></p><label>Draft name<input id="draft-name" maxlength="160" required></label><label id="responsibility-label">Responsibility<textarea id="draft-responsibility" maxlength="4000"></textarea></label><p class="muted">Saves a new draft version. Existing ownership, configuration and runtime state are preserved. No workflow runs.</p><div class="row"><button class="primary">Save corrected draft</button><button type="button" id="cancel-correct">Cancel</button></div></form></dialog><script>
const el=id=>document.getElementById(id),query=new URLSearchParams(location.search);let clients=[],snapshot,selection,editing,tab='Workflows',busy=false;const scope=()=>({client:query.get('client'),company:query.get('company')||''});
function node(tag,text,parent){let n=document.createElement(tag);n.textContent=text;if(parent)parent.append(n);return n}function button(text,fn,parent){let n=node('button',text,parent);n.type='button';n.onclick=()=>run(fn);return n}function status(s){el('status').textContent=s}
async function run(fn){if(busy)return;busy=true;el('error').textContent='';try{await fn()}catch(e){el('error').textContent=e.message}finally{busy=false}}
async function api(action,body){let path='/api/owner-support/'+action;if(!body&&['snapshot'].includes(action))path+='?'+new URLSearchParams(scope());let r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});let x=await r.json();if(!r.ok)throw Error(x.detail||'Support request failed');return x}
function cards(){el('cards').replaceChildren();let q=el('search').value.toLowerCase();for(let c of clients.filter(c=>(c.name+' '+c.code).toLowerCase().includes(q))){let card=node('article','',el('cards'));node('h2',c.name,card);node('small',c.code||'Client workspace',card);let select=node('select','',card);select.setAttribute('aria-label','Company for '+c.name);let companies=c.companies.length?c.companies:[{id:'',name:'Client view · no company configured'}];for(let co of companies){let o=node('option',co.name,select);o.value=co.id}button('Open client view',()=>{selection={client:c.id,company:select.value};el('purpose-target').textContent=c.name+' · '+select.options[select.selectedIndex].text;el('purpose').showModal()},card)}}
function latest(objects){let rows=new Map();for(let o of objects){let key=o.path.split('/')[0]+':'+o.body.id;let old=rows.get(key);if(!old||o.body.version.localeCompare(old.body.version,undefined,{numeric:true})>0)rows.set(key,o)}return [...rows.values()]}
function render(){el('content').replaceChildren();let objects=latest(snapshot.objects);if(tab==='Discovery'){if(!snapshot.discovery.length)node('p','No submitted business discovery answers for this company.',el('content'));for(let d of snapshot.discovery){let box=node('section','',el('content'));box.className='panel';node('h2',d.welcome_name+' · Discovery revision '+d.revision,box);node('small','User-supplied research answers; not independently verified',box);for(let q of d.questions){node('h3',q.question,box);let a=d.answers[q.id];node('p',a?.text||a?.status?.replaceAll('_',' ')||'Unknown',box)}}return}objects=objects.filter(o=>tab==='Workflows'?o.path.startsWith('workflows/'):tab==='Agents'?o.path.startsWith('agents/'):!o.path.startsWith('workflows/')&&!o.path.startsWith('agents/'));if(!objects.length)node('p','No '+tab.toLowerCase()+' in this company view.',el('content'));for(let o of objects){let b=o.body,box=node('section','',el('content'));box.className='panel';node('h2',b.name||b.label||b.id,box);node('small',(b.capability||b.kind||'Workflow')+' · '+(b.version||'')+' · '+(o.published?'Published':b.status||'Draft'),box);if(b.responsibility)node('p',b.responsibility,box);if(b.nodes){for(let n of b.nodes){node('h3',n.data?.guided?.name||n.data?.capability||'Agent',box);node('p',n.data?.guided?.responsibility||'Responsibility needs review',box)}}if(b.guided?.fields){let details=node('details','',box);node('summary','Design choices',details);let dl=node('dl','',details);for(let [k,v] of Object.entries(b.guided.fields)){if(v?.value==null)continue;node('dt',k.replaceAll('.',' · ').replaceAll('_',' '),dl);node('dd',typeof v.value==='object'?'Structured choice saved':String(v.value),dl)}}if((tab==='Workflows'||tab==='Agents')&&!o.published&&b.status==='draft')button('Correct draft',()=>{editing=o;el('draft-name').value=b.name||'';el('draft-responsibility').value=b.responsibility||'';el('responsibility-label').hidden=tab==='Workflows';el('draft-version').textContent='Current version '+b.version+' · A new version will be saved';el('correction').showModal()},box)}}
async function loadView(){snapshot=await api('snapshot');el('console').hidden=true;el('view').hidden=false;el('banner').hidden=false;el('target').textContent=snapshot.company?.name||snapshot.client.name;el('actor').textContent='Acting as '+snapshot.actor.name+' · '+snapshot.actor.email;el('expiry').textContent='Support expires '+new Date(snapshot.expires_at).toLocaleTimeString()+' · No business execution';el('title').textContent=snapshot.client.name;el('intro').textContent='Review client configuration and submitted business answers. Credentials, publishing and runtime actions are unavailable in support mode.';el('tabs').replaceChildren();for(let name of ['Workflows','Agents','Resources','Discovery']){let b=button(name,()=>{tab=name;render();for(let item of el('tabs').children)item.setAttribute('aria-pressed',item.textContent===name)},el('tabs'));b.setAttribute('aria-pressed',name===tab)}el('notes').replaceChildren();if(!snapshot.notes.length)node('p','No owner guidance saved.',el('notes'));for(let n of snapshot.notes){node('strong',n.category,el('notes'));node('p',n.content,el('notes'));node('small',new Date(n.created_at).toLocaleString(),el('notes'))}render()}
el('search').oninput=cards;el('cancel-open').onclick=()=>el('purpose').close();el('cancel-correct').onclick=()=>el('correction').close();el('purpose-form').onsubmit=e=>{e.preventDefault();run(async()=>{let x=await api('open',{...selection,reason:el('reason').value.trim()});location.href='/owner-support/view?'+new URLSearchParams({client:x.client,company:x.company||''})})};el('note').onsubmit=e=>{e.preventDefault();run(async()=>{await api('note',{...scope(),category:el('category').value,content:el('note-text').value.trim()});el('note-text').value='';await loadView();status('Company guidance saved. No workflow execution created.')})};el('correction-form').onsubmit=e=>{e.preventDefault();run(async()=>{let changes={name:el('draft-name').value.trim()};if(!el('responsibility-label').hidden)changes.responsibility=el('draft-responsibility').value.trim();let x=await api('correct',{...scope(),path:editing.path,expected_hash:editing.record_hash,changes});el('correction').close();await loadView();status('Corrected draft version '+x.version+' saved. Nothing was enabled.')})};el('exit').onclick=()=>run(async()=>{await api('close',scope());location.href='/owner-support'});el('show-audit').onclick=()=>run(async()=>{let x=await api('audit');el('audit').hidden=false;el('events').replaceChildren();for(let ev of x.events){let row=node('p',new Date(ev.created_at).toLocaleString()+' · '+ev.client_id+' · '+ev.action,el('events'));if(ev.evidence?.path)node('small',ev.evidence.path,row)}el('audit').scrollIntoView({behavior:'smooth'})});run(async()=>{if(location.pathname.endsWith('/view'))await loadView();else{clients=(await api('clients')).clients;cards()}});
</script></body></html>'''
GUIDANCE='''<!doctype html><html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operis · Owner guidance</title><style>body{font:16px system-ui;max-width:850px;margin:40px auto;padding:24px;background:#101923;color:#edf4f6}a{color:#80dec3}article{padding:20px;border:1px solid #536779;border-radius:12px;margin:16px 0}p{white-space:pre-wrap}</style></head><body><a href="/">← My workspace</a><h1>Owner guidance</h1><p>Suggestions and guidance for your selected company. These are not workflow executions or approvals.</p><div id="notes"></div><p id="error" role="alert"></p><script>fetch('/api/support-guidance').then(async r=>{let x=await r.json();if(!r.ok)throw Error('Guidance unavailable');let box=document.getElementById('notes');if(!x.notes.length)box.textContent='No owner guidance saved for this company.';for(let n of x.notes){let a=document.createElement('article'),h=document.createElement('h2'),p=document.createElement('p'),s=document.createElement('small');h.textContent=n.category;p.textContent=n.content;s.textContent=n.author+' · '+new Date(n.created_at).toLocaleString();a.append(h,p,s);box.append(a)}}).catch(e=>document.getElementById('error').textContent=e.message);</script></body></html>'''
